flowchart TD
    A["Low mood or loss of interest"] --> B{"SAFETY FIRST<br/>suicidal or homicidal thoughts?<br/>not eating · urgent need to treat?"}
    B -->|"Yes"| C["Urgent care · consider ECT,<br/>first line when there is an urgent need to treat"]
    B -->|"No"| D{"Ever a manic or<br/>hypomanic episode?"}
    D -->|"Yes"| E["BIPOLAR, not a depressive disorder<br/>no antidepressants"]
    D -->|"No"| F{"Explained by a substance,<br/>medication or medical illness?<br/>history · exam · labs"}
    F -->|"Yes"| G["Substance-induced, or due to<br/>another medical condition"]
    F -->|"No"| H{"5 of 9 symptoms for 2 weeks,<br/>incl. low mood or anhedonia?"}
    H -->|"Yes"| I["MAJOR DEPRESSIVE DISORDER<br/>add specifiers"]
    H -->|"No"| J{"Low mood most days<br/>for 2 years?"}
    J -->|"Yes"| K["PERSISTENT DEPRESSIVE DISORDER"]
    J -->|"No"| L["Other specified or unspecified"]
    I --> M{"Psychotic or catatonic features,<br/>or past good response to ECT?"}
    M -->|"Yes"| N["ECT first line"]
    M -->|"No"| O["FIRST LINE: SSRI + psychotherapy<br/>(cognitive behavioural or interpersonal)<br/>light therapy if seasonal pattern"]
    O --> P["Wait 4-6 weeks for a response"]
    P --> Q{"Responded?"}
    Q -->|"No"| R["Raise the dose → add a second class<br/>or augment → switch class"]
    Q -->|"Remission"| S["Continue at least 6 months,<br/>then taper slowly"]

flowchart TD
    A["Medically ill patient"] --> B["Screen: 'Do you feel depressed?'"]
    B --> C{"Hopelessness, worthlessness, guilt,<br/>anhedonia or suicidal ideation?"}
    C -->|"No"| D["Keep screening at follow-up"]
    C -->|"Yes"| E{"Acute confusion, inattention,<br/>slowed and lethargic?"}
    E -->|"Yes"| F["HYPOACTIVE DELIRIUM<br/>treat the underlying cause"]
    E -->|"No"| G{"Low mood or anhedonia most days<br/>for at least 2 weeks, meeting criteria?"}
    G -->|"Yes"| H["MAJOR DEPRESSION<br/>antidepressant · psychotherapy · ECT if needed"]
    G -->|"No, a reaction to an identifiable<br/>stressor within 3 months"| I["ADJUSTMENT DISORDER<br/>supportive psychotherapy"]
    H --> J["Unsure? consultation-liaison psychiatry"]

flowchart TD
    A["Low or abnormal mood in pregnancy<br/>or after delivery"] --> B{"Psychotic features? confusion,<br/>delusions about the baby, hallucinations"}
    B -->|"Yes"| C["POSTPARTUM PSYCHOSIS<br/>EMERGENCY - admit<br/>think bipolar disorder"]
    B -->|"No"| D{"Mild, starts a few days after birth,<br/>resolves within a few weeks?"}
    D -->|"Yes"| E["POSTPARTUM BLUES<br/>supportive care only"]
    D -->|"No"| F{"Depressive episode with onset in pregnancy<br/>or within 4 weeks of delivery?"}
    F -->|"Yes"| G["PERIPARTUM DEPRESSION<br/>screen (Edinburgh scale) · psychotherapy · SSRI"]
    G --> H{"Preceded by agitation<br/>and high energy?"}
    H -->|"Yes"| I["Suspect a BIPOLAR switch"]
